SELECT id, customer_id, start_date, monthly_fee, SUM(monthly_fee) OVER (PARTITION BY customer_id ORDER BY start_date, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW) AS running_monthly_fee, SUM(monthly_fee) OVER (PARTITION BY customer_id ORDER BY start_date, id) AS running_monthly_fee_2 FROM subscriptions WHERE start_date <= '2024-03-26' ORDER BY customer_id DESC, running_monthly_fee DESC
